JA = "書院は知の書斎である。引用付きで文書と対話する。"
EN = "Shoin is a local notebook. Citations are machine verified."


def make_store() -> Store:
    return Store(":memory:")


def seed(store: Store) -> int:
    nb = store.create_notebook("研究")
    src = store.add_source(nb.id, "txt", "doc-ja", "mem://ja", "sha-ja")
    store.add_chunks(src.id, [JA, "本日の天気は晴れ。気温は二十五度。", "猫は液体である説。"])
    src2 = store.add_source(nb.id, "txt", "doc-en", "mem://en", "sha-en")
    store.add_chunks(src2.id, [EN, "The quick brown fox jumps over the lazy dog."])
    return nb.id


class _RacyConn:
    """sqlite3.Connection proxy that injects one concurrent write (or failure)
    the first time a statement containing `trigger` executes — a deterministic
    single-threaded reproduction of the TOCTOU races Store's rowcount and
    IntegrityError guards exist to translate into typed StoreErrors."""

    def __init__(
        self,
        inner: sqlite3.Connection,
        trigger: str,
        pre_sql: str | None = None,
        pre_params: tuple = (),
        raise_exc: Exception | None = None,
    ) -> None:
        self._inner, self._trigger = inner, trigger
        self._pre_sql, self._pre_params = pre_sql, pre_params
        self._raise_exc = raise_exc
        self.fired = False

    def __getattr__(self, name: str):  # delegate commit/execute-free members
        return getattr(self._inner, name)

    def __enter__(self) -> _RacyConn:
        self._inner.__enter__()
        return self

    def __exit__(self, *a):  # type: ignore[no-untyped-def]
        return self._inner.__exit__(*a)

    def execute(self, sql: str, params: tuple = ()):  # type: ignore[no-untyped-def]
        if not self.fired and self._trigger in sql:
            self.fired = True
            if self._raise_exc is not None:
                raise self._raise_exc
            if self._pre_sql is not None:
                self._inner.execute(self._pre_sql, self._pre_params)
        return self._inner.execute(sql, params)


class TestStore(unittest.TestCase):
    def test_version(self) -> None:
        self.assertEqual(VERSION, "0.2.670")


    def test_migration_versions_strictly_increase(self) -> None:
        """_migrate_once skips `version <= current` — so a migration added
        with a duplicate or out-of-order version never applies on any
        already-migrated DB: silent schema drift with no error. Versions
        must be unique and strictly ascending (append-only)."""
        versions = [v for v, _ in MIGRATIONS]
        self.assertEqual(
            versions,
            sorted(set(versions)),
            "MIGRATIONS versions must be unique and strictly ascending",
        )

    def test_connection_pragmas(self) -> None:
        """The three connect-time PRAGMAs are load-bearing and silent if
        dropped: foreign_keys OFF turns every ON DELETE CASCADE into an
        orphan generator with no error; journal_mode other than WAL
        serializes the ThreadingHTTPServer's concurrent readers against
        the writer; busy_timeout too small surfaces 'database is locked'
        to users under contention. Assert them on a live connection."""
        with make_store() as s:
            self.assertEqual(
                s.conn.execute("PRAGMA foreign_keys").fetchone()[0], 1
            )
            self.assertEqual(
                s.conn.execute("PRAGMA busy_timeout").fetchone()[0], 5000
            )
            self.assertIn(
                s.conn.execute("PRAGMA journal_mode").fetchone()[0],
                {"wal", "memory"},  # :memory: cannot go WAL
            )
        with tempfile.TemporaryDirectory() as d:
            with Store(str(Path(d) / "wal.db")) as s2:
                self.assertEqual(
                    s2.conn.execute("PRAGMA journal_mode").fetchone()[0],
                    "wal",
                    "file-backed DB must be in WAL mode",
                )

    def test_migrate_idempotent(self) -> None:
        # Derived from MIGRATIONS, not hardcoded: a version literal here has to be
        # hand-edited on every schema addition, which is how it goes stale.
        latest = MIGRATIONS[-1][0]
        with make_store() as s:
            self.assertEqual(s.migrate(), latest)
            self.assertEqual(s.migrate(), latest)

    def test_migration_schema_version_and_tables_always_consistent(self) -> None:
        """After migrate() on a fresh file DB, all version records and their corresponding
        tables must co-exist — proving the DDL + INSERT write is atomic (no crash window)."""
        import sqlite3 as sqlite3_mod

        with tempfile.TemporaryDirectory() as d:
            db_path = str(Path(d) / "atomic.db")
            with Store(db_path):
                pass

            conn = sqlite3_mod.connect(db_path)
            try:
                versions = {
                    row[0]
                    for row in conn.execute("SELECT version FROM schema_migrations").fetchall()
                }
                tables = {
                    row[0]
                    for row in conn.execute(
                        "SELECT name FROM sqlite_master WHERE type IN ('table','index')"
                    ).fetchall()
                }
            finally:
                conn.close()

        from shoin.store import MIGRATIONS

        self.assertEqual(versions, {v for v, _ in MIGRATIONS})
        # Spot-check tables from migration 1 and indexes from migration 2
        for name in ("notebooks", "sources", "chunks", "messages", "settings"):
            self.assertIn(name, tables, f"table {name} missing after migration")
        self.assertIn("idx_sources_notebook", tables)

    def test_migration_scripts_contain_begin_commit(self) -> None:
        """The executescript calls produced by migrate() must embed BEGIN/COMMIT so
        the DDL and version-INSERT are one atomic SQLite write."""
        from shoin.store import MIGRATIONS

        for version, sql in MIGRATIONS:
            script = (
                f"BEGIN;\n{sql.strip()}\n"
                f"INSERT INTO schema_migrations(version) VALUES ({int(version)});\nCOMMIT;"
            )
            stripped = script.strip()
            self.assertTrue(stripped.startswith("BEGIN;"), f"v{version}: missing BEGIN")
            self.assertTrue(stripped.endswith("COMMIT;"), f"v{version}: missing COMMIT")
            self.assertIn(f"VALUES ({version})", stripped)

    def test_migration_4_index_exists(self) -> None:
        """Migration 4 must create idx_messages_notebook_id_desc for query performance."""
        with make_store() as s:
            names = {
                row[0]
                for row in s.conn.execute(
                    "SELECT name FROM sqlite_master WHERE type='index'"
                ).fetchall()
            }
        self.assertIn("idx_messages_notebook_id_desc", names)

    def test_notebook_crud(self) -> None:
        with make_store() as s:
            nb = s.create_notebook("  研究  ")
            self.assertEqual(nb.name, "研究")
            s.rename_notebook(nb.id, "論文")
            self.assertEqual(s.get_notebook(nb.id).name, "論文")
            self.assertEqual(len(s.list_notebooks()), 1)
            s.delete_notebook(nb.id)
            with self.assertRaises(StoreError) as cm:
                s.get_notebook(nb.id)
            self.assertEqual(cm.exception.code, "NOTEBOOK_NOT_FOUND")

