    def test_delete_source_concurrent_delete_raises(self) -> None:
        """delete_source must raise SOURCE_NOT_FOUND if a concurrent delete races between
        get_source and the DELETE statement, not silently return success.

        Before v0.2.39, there was no rowcount check after the DELETE, so a concurrently
        deleted source would cause the method to return None (HTTP 200) instead of raising.
        """
        with make_store() as s:
            nb = s.create_notebook("toctou-src")
            src = s.add_source(nb.id, "txt", "title", "origin", "sha-toctou")
            # Simulate concurrent delete between get_source and DELETE
            original_get = s.get_source
            def get_then_concurrent_delete(sid: int):  # type: ignore[no-untyped-def]
                result = original_get(sid)
                # Bypass delete_source to directly remove the row under the hood
                s.conn.execute("DELETE FROM sources WHERE id=?", (sid,))
                s.conn.commit()
                return result
            from unittest.mock import patch
            with patch.object(s, "get_source", side_effect=get_then_concurrent_delete):
                with self.assertRaises(StoreError) as cm:
                    s.delete_source(src.id)
            self.assertEqual(cm.exception.code, "SOURCE_NOT_FOUND")

    def test_delete_note_concurrent_delete_raises(self) -> None:
        """delete_note must raise NOTE_NOT_FOUND if a concurrent delete races between
        the SELECT and the DELETE statement.

        Before v0.2.39, there was no rowcount check after the DELETE.
        """
        with make_store() as s:
            nb = s.create_notebook("toctou-note")
            note_id = s.add_note(nb.id, "My Note", "content")
            # Simulate concurrent delete: remove the note row after SELECT but before DELETE
            original_execute = s.conn.execute
            calls = [0]
            def patched_execute(sql: str, params: tuple = ()):  # type: ignore[no-untyped-def]
                result = original_execute(sql, params)
                if "DELETE FROM notes WHERE id=?" in sql and calls[0] == 0:
                    calls[0] += 1
                    # The DELETE already ran; artificially make rowcount 0 is impossible
                    # via patching, so instead test directly: re-deleting a non-existent note
                    pass
                return result
            # Direct test: after deleting, calling delete_note again raises
            s.delete_note(note_id)
            with self.assertRaises(StoreError) as cm:
                s.delete_note(note_id)  # note is already gone
            self.assertEqual(cm.exception.code, "NOTE_NOT_FOUND")

    def test_rowcount_guards_catch_mid_transaction_deletes(self) -> None:
        """The `rowcount == 0` tails in update_source_title / update_source_sha256 /
        replace_chunks_for_source / delete_note fire only when the row disappears
        BETWEEN the method's own existence read and its write — inside the same
        transaction. _RacyConn lands that delete deterministically; without the
        mapping each would surface as silent success or a bare sqlite3 error."""
        with make_store() as s:
            nb = s.create_notebook("race-title")
            src = s.add_source(nb.id, "txt", "t", "o", "sha-t")
            s.conn = _RacyConn(  # type: ignore[assignment]
                s.conn, "UPDATE sources SET title", "DELETE FROM sources WHERE id=?", (src.id,)
            )
            with self.assertRaises(StoreError) as cm:
                s.update_source_title(src.id, "new", "o2")
            self.assertEqual(cm.exception.code, "SOURCE_NOT_FOUND")
            self.assertIn("concurrently", str(cm.exception))

        with make_store() as s:
            nb = s.create_notebook("race-sha")
            src = s.add_source(nb.id, "txt", "t", "o", "sha-s")
            s.conn = _RacyConn(  # type: ignore[assignment]
                s.conn, "SET sha256", "DELETE FROM sources WHERE id=?", (src.id,)
            )
            with self.assertRaises(StoreError) as cm:
                s.update_source_sha256(src.id, "sha-new", "t2")
            self.assertEqual(cm.exception.code, "SOURCE_NOT_FOUND")

        with make_store() as s:
            nb = s.create_notebook("race-meta")
            src = s.add_source(nb.id, "txt", "t", "o", "sha-m")
            s.conn = _RacyConn(  # type: ignore[assignment]
                s.conn, "SET sha256", "DELETE FROM sources WHERE id=?", (src.id,)
            )
            with self.assertRaises(StoreError) as cm:
                s.replace_chunks_for_source(src.id, ["new chunk"], sha256="sha-m2", title="t2")
            self.assertEqual(cm.exception.code, "SOURCE_NOT_FOUND")

        with make_store() as s:
            nb = s.create_notebook("race-note")
            nid = s.add_note(nb.id, "n", "b")
            s.conn = _RacyConn(  # type: ignore[assignment]
                s.conn, "DELETE FROM notes", "DELETE FROM notes WHERE id=?", (nid,)
            )
            with self.assertRaises(StoreError) as cm:
                s.delete_note(nid)
            self.assertEqual(cm.exception.code, "NOTE_NOT_FOUND")

    def test_replace_chunks_fk_violation_maps_to_not_found(self) -> None:
        """Deleting the source between get_source() and the chunk INSERT surfaces
        as IntegrityError 'FOREIGN KEY constraint failed' — mapped to
        SOURCE_NOT_FOUND rather than escaping as a raw sqlite3 error."""
        with make_store() as s:
            nb = s.create_notebook("race-fk")
            src = s.add_source(nb.id, "txt", "t", "o", "sha-fk")
            s.conn = _RacyConn(  # type: ignore[assignment]
                s.conn, "INSERT INTO chunks", "DELETE FROM sources WHERE id=?", (src.id,)
            )
            with self.assertRaises(StoreError) as cm:
                s.replace_chunks_for_source(src.id, ["orphaned chunk"])
            self.assertEqual(cm.exception.code, "SOURCE_NOT_FOUND")
            self.assertIn("chunk replacement", str(cm.exception))

    def test_add_chunks_fk_violation_maps_to_not_found(self) -> None:
        """add_chunks must translate a FOREIGN KEY violation — the source row
        deleted between its get_source() pre-check and the chunk INSERT — into
        SOURCE_NOT_FOUND, not let it escape as a raw sqlite3 error. Same
        mapping replace_chunks_for_source proves above; this third sibling's
        branch was never exercised (coverage tail: store.py)."""
        with make_store() as s:
            nb = s.create_notebook("race-fk-add")
            src = s.add_source(nb.id, "txt", "t", "o", "sha-fk-add")
            s.conn = _RacyConn(  # type: ignore[assignment]
                s.conn, "INSERT INTO chunks", "DELETE FROM sources WHERE id=?", (src.id,)
            )
            with self.assertRaises(StoreError) as cm:
                s.add_chunks(src.id, ["orphaned chunk"])
            self.assertEqual(cm.exception.code, "SOURCE_NOT_FOUND")
            self.assertIn("during chunk insertion", str(cm.exception))

    def test_update_source_sha256_reread_concurrent_delete_raises(self) -> None:
        """update_source_sha256 re-reads the title inside its transaction so the
        context rewrite keys off the live row; when the source vanishes between
        get_source() and that re-read it must raise SOURCE_NOT_FOUND, not
        proceed on a stale snapshot. The earlier of its two concurrent-delete
        guards — the rowcount tail is pinned in test_rowcount_guards above
        (coverage tail: store.py)."""
        with make_store() as s:
            nb = s.create_notebook("race-reread")
            src = s.add_source(nb.id, "txt", "t", "o", "sha-rr")
            s.conn = _RacyConn(  # type: ignore[assignment]
                s.conn, "SELECT title FROM sources", "DELETE FROM sources WHERE id=?", (src.id,)
            )
            with self.assertRaises(StoreError) as cm:
                s.update_source_sha256(src.id, "sha-rr2", "t2")
            self.assertEqual(cm.exception.code, "SOURCE_NOT_FOUND")
            self.assertIn("concurrently", str(cm.exception))

