    def test_pdf_to_text_one_bad_page_does_not_discard_good_pages(self) -> None:
        """A single page whose extract_text() raises (a real pypdf failure mode
        — malformed content stream, bad font, corrupt xref entry) must not
        discard every other page's perfectly good text. Before this fix, the
        list comprehension ran inside one shared try/except, so one bad page
        among many good ones aborted the ENTIRE document — zero content
        indexed — contradicting the project's own graceful-degradation
        principle (CLAUDE.md: "Studio outputs have fallback text...
        History_messages() survives malformed chats"), already applied the
        same way to per-batch embedding failures in pipeline.py.
        """
        from unittest.mock import MagicMock, patch

        from shoin.ingest import pdf_to_text

        try:
            import pypdf  # noqa: F401
        except ImportError:
            self.skipTest("pypdf not installed")

        good1 = MagicMock()
        good1.extract_text.return_value = "quarterly revenue grew by 12 percent"
        bad = MagicMock()
        bad.extract_text.side_effect = Exception("malformed content stream on this page")
        good2 = MagicMock()
        good2.extract_text.return_value = "board approved a new dividend policy"

        fake_reader = MagicMock()
        fake_reader.pages = [good1, bad, good2]

        with patch("pypdf.PdfReader", return_value=fake_reader):
            text, pages_failed = pdf_to_text(b"fake pdf bytes")
        self.assertIn("quarterly revenue grew by 12 percent", text)
        self.assertIn("board approved a new dividend policy", text)
        # v0.2.256: the failure is COUNTED, not just tolerated — callers must
        # be able to warn that the index holds less than the document.
        self.assertEqual(pages_failed, 1)

    def test_pdf_to_text_page_object_access_failure_skips_only_that_page(self) -> None:
        """v0.2.587: pypdf resolves page objects lazily — reader.pages[i] can
        raise (corrupt xref) before extract_text() runs. An iterator would
        abort the whole document at that page; index iteration must skip only
        the bad page, and an unenumerable page list maps to INGEST_PARSE_FAILED.
        """
        from unittest.mock import MagicMock, patch

        from shoin.ingest import IngestError, pdf_to_text

        try:
            import pypdf  # noqa: F401
        except ImportError:
            self.skipTest("pypdf not installed")

        good = MagicMock()
        good.extract_text.return_value = "recoverable text on a good page"

        class FlakyPages:
            def __len__(self) -> int:
                return 2

            def __getitem__(self, i: int) -> object:
                if i == 0:
                    raise ValueError("corrupt xref entry for page object")
                return good

        fake_reader = MagicMock()
        fake_reader.pages = FlakyPages()
        with patch("pypdf.PdfReader", return_value=fake_reader):
            text, pages_failed = pdf_to_text(b"fake pdf bytes")
        self.assertIn("recoverable text on a good page", text)
        self.assertEqual(pages_failed, 1)

        class UnenumerablePages:
            def __len__(self) -> int:
                raise ValueError("cannot read /Pages /Count")

        fake_reader2 = MagicMock()
        fake_reader2.pages = UnenumerablePages()
        with patch("pypdf.PdfReader", return_value=fake_reader2):
            with self.assertRaises(IngestError) as ctx:
                pdf_to_text(b"fake pdf bytes")
        self.assertEqual(ctx.exception.code, "INGEST_PARSE_FAILED")

