    def test_retrieve_cross_notebook(self) -> None:
        """v0.2.649: retrieve(None) spans every notebook; hits resolve their
        notebook identity via notebooks_for_sources in ONE query."""
        with make_store() as s:
            nb1 = seed(s)
            nb2 = s.create_notebook("別書院").id
            src = s.add_source(nb2, "txt", "space", "mem://sp", "sha-sp")
            s.add_chunks(src.id, ["小惑星探査機は自律航法を搭載する。"])
            hits = retrieve(s, None, "小惑星探査機", k=5)
            self.assertIn(src.id, {h.source_id for h in hits})
            scoped = retrieve(s, nb1, "小惑星探査機", k=5)
            self.assertNotIn(src.id, {h.source_id for h in scoped})
            meta = s.notebooks_for_sources([h.source_id for h in hits])
            self.assertEqual(meta[src.id], (nb2, "別書院", "space"))
            seed_src = s.add_source(nb1, "txt", "t", "mem://t", "sha-t")
            self.assertEqual(
                s.notebooks_for_sources([seed_src.id])[seed_src.id][0], nb1
            )
            self.assertEqual(s.notebooks_for_sources([]), {})

    def test_suggest_corrections_zero_hit(self) -> None:
        """v0.2.650: a zero-hit query gets the nearest in-corpus spelling —
        absent terms only (a present term is never rewritten), preferring the
        whole surface form over its own fragment, scoped to the notebook."""
        from shoin.search import suggest_corrections

        with make_store() as s:
            nb1 = s.create_notebook("気象研究").id
            src = s.add_source(nb1, "txt", "気象衛星メモ", "mem://m", "sha-m")
            s.add_chunks(src.id, ["気象衛星は赤外放射量を観測する。"])
            # One edit away inside a title's CJK run → the full term wins.
            self.assertEqual(
                suggest_corrections(s, nb1, "気海衛生"), ["気象衛星"]
            )
            # Present terms and too-short terms are never rewritten.
            self.assertEqual(suggest_corrections(s, nb1, "気象衛星"), [])
            self.assertEqual(suggest_corrections(s, nb1, "AB"), [])
            # Genuinely out-of-domain → no forced suggestion.
            self.assertEqual(suggest_corrections(s, nb1, "xyzzy"), [])
            # Scoped: a term living in ANOTHER notebook does not leak.
            nb2 = s.create_notebook("別研究").id
            src2 = s.add_source(nb2, "txt", "軌道決定資料", "mem://k", "sha-k")
            s.add_chunks(src2.id, ["軌道決定は測距と測角の合成である。"])
            self.assertEqual(suggest_corrections(s, nb1, "軌道決完"), [])
            self.assertEqual(
                suggest_corrections(s, None, "軌道決完"), ["軌道決定"]
            )

    def test_bm25_empty_query_returns_empty(self) -> None:
        """bm25_search() with an empty query string must return [] without crashing."""
        with make_store() as s:
            nb_id = seed(s)
            self.assertEqual(bm25_search(s, nb_id, "", k=5), [])

    # --- pseudo-relevance feedback (bm25_prf_search, v0.2.182) --------------

    def test_prf_expands_recall_for_vocabulary_mismatch(self) -> None:
        """A chunk sharing topical vocabulary with the top hits — but no query
        term — must surface via the feedback expansion (RM3-style PRF)."""
        from shoin.search import bm25_prf_search

        with make_store() as s:
            nb_id = s.create_notebook("prf").id
            a1 = s.add_source(nb_id, "txt", "a1", "mem://a1", "sha-a1")
            s.add_chunks(a1.id, ["書院は近世日本の学問所である。儒学を教えた。"])
            a2 = s.add_source(nb_id, "txt", "a2", "mem://a2", "sha-a2")
            s.add_chunks(a2.id, ["書院の多くは儒学教育を行う学問所だった。"])
            b = s.add_source(nb_id, "txt", "b", "mem://b", "sha-b")
            s.add_chunks(b.id, ["近世日本の学問所では儒学が中心科目だった。"])

            base = bm25_search(s, nb_id, "書院", k=5)
            self.assertTrue(base)
            self.assertFalse(any("中心科目" in h.text for h in base),
                             "baseline must not find the vocabulary-mismatch chunk")

            hits = bm25_prf_search(s, nb_id, "書院", k=5)
            self.assertTrue(any("中心科目" in h.text for h in hits),
                            "PRF expansion must surface the mismatch chunk")

    def test_prf_expanded_hits_carry_exp_flag(self) -> None:
        """v0.2.542: chunks surfaced by the feedback terms — not the user's
        own vocabulary — carry detail["exp"] so _tail_cut's term-free test
        can tell their lex==0 apart from a genuinely unmatched tail."""
        from shoin.search import bm25_prf_search

        with make_store() as s:
            nb_id = s.create_notebook("prf-flag").id
            a1 = s.add_source(nb_id, "txt", "a1", "mem://a1", "sha-a1")
            s.add_chunks(a1.id, ["書院は近世日本の学問所である。儒学を教えた。"])
            a2 = s.add_source(nb_id, "txt", "a2", "mem://a2", "sha-a2")
            s.add_chunks(a2.id, ["書院の多くは儒学教育を行う学問所だった。"])
            b = s.add_source(nb_id, "txt", "b", "mem://b", "sha-b")
            s.add_chunks(b.id, ["近世日本の学問所では儒学が中心科目だった。"])

            hits = bm25_prf_search(s, nb_id, "書院", k=5)
            tagged = [h for h in hits if h.detail.get("exp")]
            self.assertTrue(tagged, "expansion-surfaced hits must be flagged")
            self.assertTrue(all("書院" not in h.text for h in tagged))
            untagged = [h for h in hits if not h.detail.get("exp")]
            self.assertTrue(untagged)
            self.assertTrue(all("書院" in h.text for h in untagged))

    def test_prf_counts_variant_spellings_as_one_term(self) -> None:
        """v0.2.544: the MIN_DOCS gate counts folded grams — a topical term
        spelled データベース in one feedback hit and でーたべーす in another
        is ONE term, not two half-evidences that both starve below the
        gate."""
        from shoin.search import bm25_prf_search

        with make_store() as s:
            nb_id = s.create_notebook("prf-fold").id
            a1 = s.add_source(nb_id, "txt", "a1", "mem://a1", "sha-a1")
            s.add_chunks(a1.id, ["猫の観察メモ。データベース設計の要点も記す。"])
            a2 = s.add_source(nb_id, "txt", "a2", "mem://a2", "sha-a2")
            s.add_chunks(a2.id, ["猫の飼育記録。でーたべーす正規化の話題あり。"])
            b = s.add_source(nb_id, "txt", "b", "mem://b", "sha-b")
            s.add_chunks(b.id, ["データベース移行の手順書。"])

            base = bm25_search(s, nb_id, "猫", k=5)
            self.assertFalse(any("移行" in h.text for h in base))
            hits = bm25_prf_search(s, nb_id, "猫", k=5)
            self.assertTrue(
                any("移行" in h.text for h in hits),
                "folded gram evidence must surface the topical doc")

    def test_prf_skips_when_fewer_than_min_feedback_docs(self) -> None:
        """Fewer than PRF_MIN_DOCS feedback hits means no expansion evidence —
        the result list must be returned unchanged (single-doc drift guard)."""
        from shoin.search import bm25_prf_search

        with make_store() as s:
            nb_id = s.create_notebook("prf1").id
            a1 = s.add_source(nb_id, "txt", "a1", "mem://a1", "sha-a1")
            s.add_chunks(a1.id, ["書院は近世日本の学問所である。儒学を教えた。"])
            b = s.add_source(nb_id, "txt", "b", "mem://b", "sha-b")
            s.add_chunks(b.id, ["近世日本の学問所では儒学が中心科目だった。"])

            base = bm25_search(s, nb_id, "書院", k=5)
            self.assertEqual(len(base), 1)
            hits = bm25_prf_search(s, nb_id, "書院", k=5)
            self.assertEqual([h.chunk_id for h in hits], [h.chunk_id for h in base],
                             "with one feedback doc the result must not change")

    def test_prf_skips_when_pool_already_filled(self) -> None:
        """A first pass at capacity has no recall head-room: no second pass."""
        from unittest.mock import patch

        from shoin import search as search_mod

        with make_store() as s:
            nb_id = seed(s)
            with patch.object(search_mod, "bm25_search", wraps=search_mod.bm25_search) as spy:
                hits = search_mod.bm25_prf_search(s, nb_id, "書斎", k=1)
            self.assertTrue(hits)
            # First pass fills k=1 → the expanded pass must never run.
            self.assertEqual(spy.call_count, 1)

